const t0=Date.now();
function placements(N,L){
  const list=[];
  for(let r=0;r<N;r++)for(let c=0;c<N;c++){
    const dirs = L===1?[[0,1]]:[[0,1],[1,0]];
    for(const [dr,dc] of dirs){
      const cells=[]; let ok=true;
      for(let i=0;i<L;i++){const rr=r+dr*i,cc=c+dc*i; if(rr>=N||cc>=N){ok=false;break;} cells.push(rr*N+cc);}
      if(ok) list.push(cells);
    }
  }
  return list;
}
function masks(N,cells){
  // 64 cells -> 2 words of 32 bits
  let o0=0,o1=0,h0=0,h1=0;
  const set=(w,b)=>b<32?[1<<b,0]:[0,1<<(b-32)];
  for(const c of cells){ const [a,b]=set(0,c); o0|=a;o1|=b;
    const r=(c/N)|0, cc=c%N;
    for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){
      const rr=r+dr, c2=cc+dc; if(rr<0||rr>=N||c2<0||c2>=N)continue;
      const [x,y]=set(0,rr*N+c2); h0|=x;h1|=y;
    }
  }
  return {o0,o1,h0,h1,cells};
}
const N=8;
const P={};
for(const L of [1,2,3,4]) P[L]=placements(N,L).map(c=>masks(N,c));
console.log("8x8 placements per length:", Object.fromEntries(Object.entries(P).map(([k,v])=>[k,v.length])));

function countFleet(P, fleet, noTouch){
  // fleet: array of lengths desc; identical lengths use increasing index (canonical => counts SETS)
  const groups=[]; for(const L of fleet){ if(groups.length&&groups[groups.length-1].L===L) groups[groups.length-1].n++; else groups.push({L,n:1}); }
  let total=0;
  const stack=[];
  function rec(gi, ki, startIdx, o0,o1,h0,h1){
    if(gi>=groups.length){ total++; return; }
    const g=groups[gi]; const list=P[g.L];
    for(let i=startIdx;i<list.length;i++){
      const p=list[i];
      if(noTouch){ if((p.o0&h0)||(p.o1&h1)) continue; }
      else { if((p.o0&o0)||(p.o1&o1)) continue; }
      const no0=o0|p.o0,no1=o1|p.o1,nh0=h0|p.h0,nh1=h1|p.h1;
      if(ki+1<g.n) rec(gi,ki+1,i+1,no0,no1,nh0,nh1);
      else rec(gi+1,0,0,no0,no1,nh0,nh1);
    }
  }
  rec(0,0,0,0,0,0,0);
  return total;
}
for (const [name,fleet] of [["[4,3,3,2]",[4,3,3,2]],["[4,3,3,2,2]",[4,3,3,2,2]]]){
