    const c=countFleet(P,fleet,nt);
    console.log(`8x8 ${name} noTouch=${nt}: ${c.toLocaleString("en-US")}  (${Date.now()-s} ms)`);
  }
}
console.log("total", Date.now()-t0,"ms");
