const N=8;
function placements(N,L){const list=[];for(let r=0;r<N;r++)for(let c=0;c<N;c++){const dirs=L===1?[[0,1]]:[[0,1],[1,0]];for(const[dr,dc]of dirs){const cells=[];let ok=true;for(let i=0;i<L;i++){const rr=r+dr*i,cc=c+dc*i;if(rr>=N||cc>=N){ok=false;break;}cells.push(rr*N+cc);}if(ok)list.push(cells);}}return list;}
function mk(cells){let o0=0,o1=0,h0=0,h1=0;const put=(b,w)=>{if(b<32){if(w)h0|=1<<b;else o0|=1<<b;}else{if(w)h1|=1<<(b-32);else o1|=1<<(b-32);}};
 for(const c of cells){put(c,0);const r=(c/N)|0,cc=c%N;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const rr=r+dr,c2=cc+dc;if(rr<0||rr>=N||c2<0||c2>=N)continue;put(rr*N+c2,1);}}
 return{o0,o1,h0,h1,cells};}
const L4=placements(N,4).map(mk),L3=placements(N,3).map(mk),L2=placements(N,2).map(mk);
const SLOT=[L4,L3,L3,L2], PBASE=[0,80,80,176];
const C=3562232;
const occ0=new Int32Array(C),occ1=new Int32Array(C),ships=new Uint8Array(C*4);
let n=0;
for(let a=0;a<80;a++){const A=L4[a];
 for(let b=0;b<96;b++){const B=L3[b];if(B.o0&A.h0||B.o1&A.h1)continue;const g0=A.h0|B.h0,g1=A.h1|B.h1,p0=A.o0|B.o0,p1=A.o1|B.o1;
  for(let c=b+1;c<96;c++){const Cc=L3[c];if(Cc.o0&g0||Cc.o1&g1)continue;const q0=g0|Cc.h0,q1=g1|Cc.h1,r0=p0|Cc.o0,r1=p1|Cc.o1;
   for(let d=0;d<112;d++){const D=L2[d];if(D.o0&q0||D.o1&q1)continue;occ0[n]=r0|D.o0;occ1[n]=r1|D.o1;const z=n*4;ships[z]=a;ships[z+1]=b;ships[z+2]=c;ships[z+3]=d;n++;}}}}
// seeded rng
function rng(seed){let s=seed>>>0;return()=>{s^=s<<13;s>>>=0;s^=s>>>17;s^=s<<5;s>>>=0;return s/4294967296;};}
const bitOf=c=>c<32?(1<<c):(1<<(c-32));
const wordOf=c=>c<32?0:1;

function playGame(seed,{defender="max",playerPolicy="split"}={}){
 const alive=new Int32Array(C);for(let i=0;i<C;i++)alive[i]=i;let aliveN=C;
 const rnd=rng(seed);
 const shot=new Uint8Array(64); const shotMask=[0,0];
 let shots=0,hitsGiven=0,kills=0,ms=0;
 const trail=[];
 // fixed truth for the static defender
 const truth=alive[Math.floor(rnd()*aliveN)];
 while(kills<4&&shots<64){
  const t0=process.hrtime.bigint();
  // ---- player picks a cell ----
  let cell=-1;
  if(playerPolicy==="split"){
   const m4=new Int32Array(80),m3=new Int32Array(96),m2=new Int32Array(112);
   for(let i=0;i<aliveN;i++){const q=alive[i]*4;m4[ships[q]]++;m3[ships[q+1]]++;m3[ships[q+2]]++;m2[ships[q+3]]++;}
   const cellCnt=new Float64Array(64);
   for(let i=0;i<80;i++)if(m4[i])for(const c of L4[i].cells)cellCnt[c]+=m4[i];
   for(let i=0;i<96;i++)if(m3[i])for(const c of L3[i].cells)cellCnt[c]+=m3[i]; // both slots already summed
   for(let i=0;i<112;i++)if(m2[i])for(const c of L2[i].cells)cellCnt[c]+=m2[i];
   let best=Infinity;
   for(let c=0;c<64;c++){if(shot[c])continue;const occN=cellCnt[c];const worst=Math.max(occN,aliveN-occN);if(worst<best){best=worst;cell=c;}}
  } else { // parity hunt/target, human-ish
   // target: any unshot neighbour of a live hit
   let cands=[];
   for(let c=0;c<64;c++){if(shot[c]!==2)continue;const r=(c/8)|0,cc=c%8;
     for(const[dr,dc]of[[0,1],[0,-1],[1,0],[-1,0]]){const rr=r+dr,c2=cc+dc;if(rr<0||rr>7||c2<0||c2>7)continue;const t=rr*8+c2;if(!shot[t])cands.push(t);}}
   if(!cands.length){for(let c=0;c<64;c++){const r=(c/8)|0,cc=c%8;if(!shot[c]&&((r+cc)%2===0))cands.push(c);}}
   if(!cands.length){for(let c=0;c<64;c++)if(!shot[c])cands.push(c);}
   cell=cands[Math.floor(rnd()*cands.length)];
  }
  const w=wordOf(cell),bit=bitOf(cell);
  const occA=w===0?occ0:occ1;
  // ---- defender partitions ----
  const buckets=new Map(); // key -> {count, first}
  const nshot0=shotMask[0]|(w===0?bit:0), nshot1=shotMask[1]|(w===1?bit:0);
  for(let i=0;i<aliveN;i++){const id=alive[i];
    let key;
    if(!(occA[id]&bit)) key=0;
    else{
      const q=id*4;let slot=-1;
      for(let s=0;s<4;s++){const p=SLOT[s][ships[q+s]];if((w===0?p.o0:p.o1)&bit){slot=s;break;}}
      const p=SLOT[slot][ships[q+slot]];
      const dead=((p.o0&~nshot0)===0)&&((p.o1&~nshot1)===0);
      key=dead?2+PBASE[slot]+ships[q+slot]:1;
    }
    let b=buckets.get(key);if(!b){b={c:0,f:id};buckets.set(key,b);}b.c++;
  }
  let chosen=-1,bestC=-1;
  if(defender==="static"){ // answer as the fixed truth would
    const id=truth;let key;
    if(!(occA[id]&bit))key=0;else{const q=id*4;let slot=-1;for(let s=0;s<4;s++){const p=SLOT[s][ships[q+s]];if((w===0?p.o0:p.o1)&bit){slot=s;break;}}
      const p=SLOT[slot][ships[q+slot]];const dead=((p.o0&~nshot0)===0)&&((p.o1&~nshot1)===0);key=dead?2+PBASE[slot]+ships[q+slot]:1;}
    chosen=key;
  } else {
    for(const[k,b]of buckets){const v=defender==="max"?b.c:-b.c;if(v>bestC){bestC=v;chosen=k;}}
  }
  // ---- filter ----
  let wIdx=0;
  for(let i=0;i<aliveN;i++){const id=alive[i];let key;
    if(!(occA[id]&bit))key=0;else{const q=id*4;let slot=-1;for(let s=0;s<4;s++){const p=SLOT[s][ships[q+s]];if((w===0?p.o0:p.o1)&bit){slot=s;break;}}
      const p=SLOT[slot][ships[q+slot]];const dead=((p.o0&~nshot0)===0)&&((p.o1&~nshot1)===0);key=dead?2+PBASE[slot]+ships[q+slot]:1;}
    if(key===chosen)alive[wIdx++]=id;}
  aliveN=wIdx;
  shotMask[0]=nshot0;shotMask[1]=nshot1;
  shot[cell]=chosen===0?1:2; shots++;
  if(chosen>=1)hitsGiven++;
  if(chosen>=2){kills++;
    // no-touch halo of the dead ship is provably empty -> auto-mark (free info, no cost)
  }
  ms+=Number(process.hrtime.bigint()-t0)/1e6;
  trail.push({shots,aliveN,ans:chosen===0?"MISS":chosen===1?"HIT":"KILL"});
 }
 return{shots,kills,aliveN,ms,trail};
}
for(const def of ["static","max"]){
 for(const pol of ["split","human"]){
  let tot=0,totMs=0,worst=0,runs=def==="max"&&pol==="split"?5:5;
