cd /c/dev && node --input-type=module --max-old-space-size=4096 -e '
// ---- generic board/placement machinery for any N, 4 words x 25 bits (N<=10) ----
function mkBoard(N){
 const W=Math.ceil(N*N/25);
 const placements=(L)=>{const list=[];for(let r=0;r<N;r++)for(let c=0;c<N;c++){const dirs=L===1?[[0,1]]:[[0,1],[1,0]];for(const[dr,dc]of dirs){const cells=[];let ok=true;for(let i=0;i<L;i++){const rr=r+dr*i,cc=c+dc*i;if(rr>=N||cc>=N){ok=false;break;}cells.push(rr*N+cc);}if(ok)list.push(cells);}}return list;};
 const mk=(cells)=>{const o=new Int32Array(W),h=new Int32Array(W);
  const set=(arr,b)=>{arr[(b/25)|0]|=1<<(b%25);};
  for(const c of cells){set(o,c);const r=(c/N)|0,cc=c%N;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const rr=r+dr,c2=cc+dc;if(rr<0||rr>=N||c2<0||c2>=N)continue;set(h,rr*N+c2);}}
  return{o,h,cells};};
 return{N,W,list:L=>placements(L).map(mk)};
}
function rngF(seed){let s=seed>>>0||1;return()=>{s^=s<<13;s>>>=0;s^=s>>>17;s^=s<<5;s>>>=0;return s/4294967296;};}
// ---- SIS counting estimator (canonical order => counts SETS directly) ----
function sis(board,fleet,K,seed,noTouch=true){
 const W=board.W;
 const byLen={};for(const L of new Set(fleet))byLen[L]=board.list(L);
 const order=[...fleet].sort((a,b)=>b-a);
 const rnd=rngF(seed);
 let sum=0,sum2=0,dead=0;
 const cand=new Int32Array(400);
 for(let k=0;k<K;k++){
  const occ=new Int32Array(W),halo=new Int32Array(W);
  let w=1,ok=true,prevLen=-1,prevIdx=-1;
  for(const L of order){
   const list=byLen[L];
   const start=(L===prevLen)?prevIdx+1:0;
   let nc=0;
   for(let i=start;i<list.length;i++){const p=list[i];let bad=false;
    if(noTouch){for(let x=0;x<W;x++)if(p.o[x]&halo[x]){bad=true;break;}}
    else{for(let x=0;x<W;x++)if(p.o[x]&occ[x]){bad=true;break;}}
    if(!bad)cand[nc++]=i;}
   if(nc===0){ok=false;break;}
   w*=nc;
   const pick=cand[(rnd()*nc)|0];const p=list[pick];
   for(let x=0;x<W;x++){occ[x]|=p.o[x];halo[x]|=p.h[x];}
   prevLen=L;prevIdx=pick;
  }
  if(!ok){dead++;continue;}
  sum+=w;sum2+=w*w;
 }
 const mean=sum/K, varr=sum2/K-mean*mean, se=Math.sqrt(varr/K);
 return{est:mean,se,rse:se/mean,deadFrac:dead/K};
}
