// Воркер собирается из строки — ни одного файла рядом со страницей, как и спрайты
// в nostromo-gambit собираются из ASCII, а не лежат картинками.
const worker = new Worker(URL.createObjectURL(
  new Blob([ORACLE_SOURCE], { type: 'text/javascript' })));

